"""Authored synthetic cases for a document-route screen. Never pass the grading key into generation."""
# id, family, question, three one-page extracts (title, text), gold conclusion, mandatory limiting or contrary evidence
ROWS = [
 ('rebate','definition','Did the East region qualify for the full rebate under the signed rule?', [('Terms','East earns the full rebate only for at least 100 accepted units during the period.'),('Dispatch','East dispatched 105 units during the period. Dispatch is recorded before inspection.'),('Inspection','East accepted 96 units during the period. The remainder awaited inspection.')], 'No. Accepted units are below the threshold.', 'Contrast 105 dispatched with 96 accepted; accepted, not dispatched, are compared to 100.'),
 ('liquidity','definition','Did West meet its quarter-end unrestricted cash floor?', [('Covenant','West must hold at least 50 million dollars of unrestricted cash at quarter end.'),('Flash','The preliminary quarter-end total cash figure for West was 48 million dollars.'),('Signed','The signed quarter-end reconciliation supersedes the flash and records 52 million dollars of unrestricted cash for West.')], 'Yes. Signed unrestricted cash of 52 million exceeds the floor of 50 million.', 'Distinguish the superseded preliminary 48 from signed unrestricted cash of 52.'),
 ('recall','scope','Can we conclude that the recall was closed for all product lines?', [('Bulletin','The central bulletin described the recall as closed for all lines.'),('Correction','The recall bulletin author corrected the scope: closure was verified for the Blue line only.'),('Register','The register has no verified status entry for the Green line; a blank entry does not mean open or closed.')], 'No group-wide conclusion is established; Green is unknown, not proven open.', 'The correction covers Blue only, and the blank for Green is unknown despite the original bulletin.'),
 ('fees','scope','Does the evidence establish that every customer cohort paid a lower fee?', [('Memo','The fee notice proposed a reduction for every customer cohort.'),('Invoices','The audited invoices show a lower paid fee for both the retail cohort and the wholesale cohort.'),('Register','The signed cohort register confirms retail and wholesale were the only customer cohorts during the invoice period.')], 'Yes. Both and all registered cohorts actually paid less.', 'The proposal alone is insufficient; actual invoices cover both and the register confirms those are all cohorts.'),
 ('vote','authority','Was the Cedar proposal approved at the close of the meeting?', [('Draft','The draft minutes described Cedar as approved by voice vote.'),('Rule','The meeting rule makes the signed final minutes controlling over draft minutes.'),('Final','The signed final minutes for the same meeting record the Cedar vote as deferred, not approved.')], 'No. The controlling final minutes record deferral.', 'Acknowledge the contrary draft approval and explain why the signed final minutes control.'),
 ('audit','authority','Do the records establish that the audit opinion was unqualified?', [('Brief','Management expected an unqualified audit opinion.'),('Dispatch','The cover letter confirms that a signed audit opinion was delivered, without stating its wording.'),('Index','The document index lists the opinion itself as unavailable; the index does not describe its contents.')], 'Not established; delivery is not the wording of the opinion.', 'Distinguish expectation and proof of delivery from the unavailable actual opinion or its wording.'),
 ('uptime','measurement','Did the service exceed its monthly uptime commitment?', [('Policy','The monthly uptime commitment was strictly above 99 percent for the entire month.'),('Dashboard','The dashboard showed 99.8 percent uptime for the first week only.'),('Ledger','The signed full-month uptime ledger shows exactly 99 percent for that month.')], 'No. Exactly 99 percent does not exceed a strictly-above-99 requirement.', 'The first-week number is not full-month evidence and exactly 99 is not above the requirement.'),
 ('staff','measurement','Can the records establish that the staffing target was reached at both sites?', [('Target','The staffing target requires at least 20 on-duty staff at each site on Tuesday.'),('Roster','The Tuesday staffing roster lists 23 on duty at North and 22 assigned at South; assigned is not the same as on duty.'),('Signoff','Tuesday staffing sign-off confirms the North on-duty count. The South on-duty count was not recorded.')], 'Not established for both; North meets the threshold, South is unknown.', 'Distinguish South assigned from South on-duty, which was not recorded, despite North confirmation.')]

def prepare(row):
 ident,family,question,sources,gold,counter=row
 return {'case':ident,'family':family,'question':question,'documents':[{'id':str(i),'name':name+'.pdf','pages':[text]} for i,(name,text) in enumerate(sources)],'gold':gold,'counter':counter}

def cases():return [prepare(r) for r in ROWS]

def generation_view(c):return {k:c[k] for k in ('case','question','documents')}
